if (typeof width === 'undefined') { var width = 1280; }
if (typeof height === 'undefined') { var height = 720; }


// --- Global Variables for Uncler M Variants ---
var uM_colors = ["#f97316", "#ef4444", "#ec4899", "#8b5cf6", "#facc15"];
var speedMult = 1.0;
var lineScale = 1.0;
var dynamicShift = 0;
var scalePulse = 1.0;
var rotAngle = 0;
var gridOffset = 0;
var uM_rot = 0;

// === Inspired by 'Linezoom' by 'Taoidal' ===
// Created as variant #3 by Uncler M
// Infused with creative algorithmic modifications.

// === Tab: mySketch ===
// Made for #WCCChallenge
// If you haven't tried it yet, zoom into a line until it fills your whole screen.

let mindim;
let lines = [];
inverseMode = false;

function setup() {
	mindim = max(windowWidth, windowHeight);
	createCanvas(mindim, mindim);
	background(10, 10, 15);
}

function distToLine(x,y,x1,y1,x2,y2){
	let ldx = x2-x1;
	let ldy = y2-y1;
	let magSq = ldx*ldx + ldy*ldy;
	return abs((x-x1)*ldy - (y-y1)*ldx)/sqrt(magSq);
}

function addRandomLine(){
	let cx = random()*2-1;
	let cy = random()*2-1;
	let theta = random()*TAU;
	let dist = random()*0.2+0.1;
	lines.push([cx+dist*cos(theta),cy+dist*sin(theta),cx-dist*cos(theta),cy-dist*sin(theta),0.00006]);
}

function update(){
	newLines = [];
	let ox = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/mindim*2-1;
	let oy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/mindim*2-1;
	for(let l of lines){
		l[0] = (l[0]-ox)*1.02+ox;
		l[1] = (l[1]-oy)*1.02+oy;
		l[2] = (l[2]-ox)*1.02+ox;
		l[3] = (l[3]-oy)*1.02+oy;
		l[4] = l[4]*1.02;
		if(l[4]>12)
		l[4] = l[4]*(1-l[4]*0.0001);
		if((l[0]<-1-l[4] && l[2]<-1-l[4]) || (l[1]<-1-l[4] && l[3]<-1-l[4]) || (l[0]>1+l[4] && l[2]>1+l[4]) || (l[1]>1+l[4] && l[3]>1+l[4]))continue;
		if(distToLine(0,0,l[0],l[1],l[2],l[3])>1.414+l[4]/2)continue;
		newLines.push(l);
		if(distToLine(0,0,l[0],l[1],l[2],l[3])<l[4]/2-1.5){
			inverseMode = !inverseMode;
			newLines = [];
			break;
		}
	}
	lines = newLines;
	for(let i=0; i<50; i++)
	addRandomLine();
}

function draw() {
  // === Variant 3: Fractal Orbit Matrix ===
  gridOffset = noise(frameCount * 0.01) * 80;
  push();
  translate(gridOffset, -gridOffset);

		background(10, 10, 15);
	if(!inverseMode){
		stroke(22);
	}else{
		noStroke();
		fill(22);
		rect(0,0,mindim,mindim);
		stroke(244);
	}
	noFill();
	for(let l of lines){
		strokeWeight(l[4]*mindim/2);
		line(mindim/2*(1+l[0]),mindim/2*(1+l[1]),mindim/2*(1+l[2]),mindim/2*(1+l[3]));
	}
	update();

  pop();
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
